-- ═════════ 0005_search.sql ═════════
-- Storefront search, filters and facets. SECURITY INVOKER: RLS limits results to published products for visitors.

create or replace function category_descendants(p_category uuid) returns setof uuid language sql stable as $$
  with recursive t as (
    select id from categories where id = p_category
    union all
    select c.id from categories c join t on c.parent_id = t.id
  ) select id from t
$$;

-- Lowest sellable price for a product (family price or cheapest active variant); null = quote only.
create or replace function product_display_price(p_product uuid) returns numeric language sql stable as $$
  select coalesce(
    (select base_price from products where id = p_product and not is_quote_only),
    (select min(v.price) from product_variants v join products p on p.id = v.product_id
      where v.product_id = p_product and v.is_active and v.price is not null and not p.is_quote_only))
$$;

-- p_filters example: {"size":["2\""],"grade":["304","316"]}  (OR within one attribute, AND across attributes)
create or replace function search_products(
  p_q text default null,
  p_category uuid default null,
  p_filters jsonb default '{}'::jsonb,
  p_availability text default null,       -- 'in_stock' | 'quote_only' | 'priced'
  p_flag text default null,               -- 'featured' | 'new' | 'offer'
  p_sort text default 'newest',           -- newest | name_asc | price_low | price_high | popular
  p_limit int default 24,
  p_offset int default 0
) returns table (id uuid, total bigint)
language plpgsql stable as $$
declare k text; vals text[]; q text := nullif(trim(p_q), '');
begin
  return query
  with filtered as (
    select p.id, p.name_en, p.published_at, p.view_count, product_display_price(p.id) as dprice
    from products p
    where p.status = 'published'
      and (p_category is null or p.category_id in (select category_descendants(p_category)))
      and (q is null or p.name_en ilike '%'||q||'%' or p.name_ar ilike '%'||q||'%' or p.sku ilike '%'||q||'%'
           or p.short_desc_en ilike '%'||q||'%' or p.description_en ilike '%'||q||'%'
           or exists (select 1 from product_variants v where v.product_id = p.id and v.sku ilike '%'||q||'%')
           or exists (select 1 from product_attribute_values a where a.product_id = p.id and (a.value_en ilike '%'||q||'%' or a.value_ar ilike '%'||q||'%'))
           or exists (select 1 from brands b where b.id = p.brand_id and b.name ilike '%'||q||'%'))
      and (p_flag is null or (p_flag = 'featured' and p.is_featured) or (p_flag = 'new' and p.is_new_arrival) or (p_flag = 'offer' and p.is_special_offer))
      and (p_availability is null
           or (p_availability = 'quote_only' and p.is_quote_only)
           or (p_availability = 'priced' and not p.is_quote_only)
           or (p_availability = 'in_stock' and exists (select 1 from variant_availability va where va.product_id = p.id and va.available > 0)))
      and not exists (
        select 1 from jsonb_each(coalesce(p_filters, '{}'::jsonb)) f
        where jsonb_typeof(f.value) = 'array' and jsonb_array_length(f.value) > 0
          and not exists (
            select 1 from product_attribute_values a join attribute_defs d on d.id = a.attribute_id
            where a.product_id = p.id and d.key = f.key and a.value_en in (select jsonb_array_elements_text(f.value))))
  )
  select f.id, count(*) over () as total from filtered f
  order by
    case when p_sort = 'name_asc' then f.name_en end asc,
    case when p_sort = 'price_low' then f.dprice end asc nulls last,
    case when p_sort = 'price_high' then f.dprice end desc nulls last,
    case when p_sort = 'popular' then f.view_count end desc,
    f.published_at desc nulls last, f.name_en
  limit least(greatest(p_limit,1),100) offset greatest(p_offset,0);
end $$;
grant execute on function search_products(text,uuid,jsonb,text,text,text,int,int) to anon, authenticated;

-- Facet counts for the filter sidebar (within category + search scope, ignoring other facet selections for simplicity).
create or replace function product_facets(p_q text default null, p_category uuid default null)
returns table (attr_key text, attr_name_en text, attr_name_ar text, value_en text, value_ar text, n bigint)
language sql stable as $$
  select d.key, d.name_en, d.name_ar, a.value_en, max(a.value_ar), count(distinct a.product_id)
  from product_attribute_values a
  join attribute_defs d on d.id = a.attribute_id and d.is_filterable
  join products p on p.id = a.product_id and p.status = 'published'
  where (p_category is null or p.category_id in (select category_descendants(p_category)))
    and (nullif(trim(p_q),'') is null or p.name_en ilike '%'||trim(p_q)||'%' or p.name_ar ilike '%'||trim(p_q)||'%' or p.sku ilike '%'||trim(p_q)||'%')
  group by d.key, d.name_en, d.name_ar, d.sort_order, a.value_en
  order by d.sort_order, d.key, a.value_en
$$;
grant execute on function product_facets(text,uuid) to anon, authenticated;

-- Type-ahead suggestions: products (prefix matches first) and categories.
create or replace function search_suggestions(p_q text, p_limit int default 6)
returns table (kind text, id uuid, slug text, name_en text, name_ar text, image_path text)
language sql stable as $$
  (select 'product'::text, p.id, p.slug, p.name_en, p.name_ar,
          (select i.storage_path from product_images i where i.product_id = p.id order by i.is_primary desc, i.sort_order limit 1)
   from products p
   where p.status = 'published' and length(trim(p_q)) >= 2
     and (p.name_en ilike '%'||trim(p_q)||'%' or p.name_ar ilike '%'||trim(p_q)||'%' or p.sku ilike trim(p_q)||'%')
   order by (p.name_en ilike trim(p_q)||'%') desc, p.view_count desc limit p_limit)
  union all
  (select 'category'::text, c.id, c.slug, c.name_en, c.name_ar, c.image_path
   from categories c
   where c.is_active and length(trim(p_q)) >= 2 and (c.name_en ilike '%'||trim(p_q)||'%' or c.name_ar ilike '%'||trim(p_q)||'%')
   limit 3)
$$;
grant execute on function search_suggestions(text,int) to anon, authenticated;

-- ═════════ 0006_rfq_respond.sql ═════════
-- Customer response to a quotation (by emailed token or while signed in). No direct table write is granted.
create or replace function respond_rfq(p_token uuid, p_accept boolean) returns text
language plpgsql security definer set search_path = public as $$
declare r rfqs%rowtype;
begin
  select * into r from rfqs where access_token = p_token for update;
  if not found then raise exception 'Quotation not found'; end if;
  if r.status <> 'quoted' then raise exception 'This quotation can no longer be changed'; end if;
  if r.quote_valid_until is not null and r.quote_valid_until < current_date then
    update rfqs set status = 'expired' where id = r.id;
    insert into rfq_events (rfq_id, event, detail) values (r.id, 'expired', 'Validity date passed');
    raise exception 'This quotation has expired; please request a new one';
  end if;
  update rfqs set status = case when p_accept then 'accepted'::rfq_status else 'rejected'::rfq_status end where id = r.id;
  insert into rfq_events (rfq_id, event, detail, actor) values (r.id, case when p_accept then 'customer_accepted' else 'customer_rejected' end, null, auth.uid());
  return case when p_accept then 'accepted' else 'rejected' end;
end $$;
grant execute on function respond_rfq(uuid, boolean) to anon, authenticated;

-- Mark overdue quotations as expired (call from a scheduled job or on admin page load).
create or replace function expire_overdue_quotations() returns int language plpgsql security definer set search_path = public as $$
declare n int;
begin
  if not is_staff() then raise exception 'Not authorised'; end if;
  update rfqs set status = 'expired' where status = 'quoted' and quote_valid_until < current_date;
  get diagnostics n = row_count;
  return n;
end $$;
revoke all on function expire_overdue_quotations() from public, anon;
grant execute on function expire_overdue_quotations() to authenticated;

-- ═════════ 0007_reports.sql ═════════
-- Reporting functions (staff only). Revenue excludes cancelled/refunded orders. All figures come from real rows.

create or replace function admin_sales_report(p_from date, p_to date, p_group text default 'day')
returns table (period date, orders bigint, subtotal numeric, vat numeric, total numeric, paid numeric)
language sql stable security definer set search_path = public as $$
  select date_trunc(case when p_group = 'month' then 'month' else 'day' end, o.created_at at time zone 'Asia/Riyadh')::date as period,
         count(*), coalesce(sum(o.subtotal),0), coalesce(sum(o.vat_total),0), coalesce(sum(o.grand_total),0), coalesce(sum(o.amount_paid),0)
  from orders o
  where is_staff() and o.status not in ('cancelled','refunded')
    and (o.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to
  group by 1 order by 1
$$;

create or replace function admin_sales_by_product(p_from date, p_to date, p_limit int default 50)
returns table (product_id uuid, name text, sku text, units numeric, revenue numeric, cost numeric, profit numeric)
language sql stable security definer set search_path = public as $$
  -- cost/profit are computed ONLY on lines whose purchase cost was known when the order was placed
  select oi.product_id, max(oi.name_en), max(oi.sku), sum(oi.quantity), sum(oi.line_total),
         coalesce(sum(c.unit_cost * oi.quantity), 0), coalesce(sum(oi.line_total - c.unit_cost * oi.quantity) filter (where c.unit_cost is not null), 0)
  from order_items oi join orders o on o.id = oi.order_id left join order_item_costs c on c.order_item_id = oi.id
  where is_staff() and o.status not in ('cancelled','refunded') and (o.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to
  group by oi.product_id order by sum(oi.line_total) desc limit least(p_limit, 500)
$$;

create or replace function admin_sales_by_category(p_from date, p_to date)
returns table (category text, units numeric, revenue numeric)
language sql stable security definer set search_path = public as $$
  select coalesce(cat.name_en, 'Uncategorised'), sum(oi.quantity), sum(oi.line_total)
  from order_items oi join orders o on o.id = oi.order_id
  left join products p on p.id = oi.product_id left join categories cat on cat.id = p.category_id
  where is_staff() and o.status not in ('cancelled','refunded') and (o.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to
  group by 1 order by 3 desc
$$;

create or replace function admin_traffic(p_from date, p_to date)
returns table (day date, visitors bigint, page_views bigint, product_views bigint, searches bigint, whatsapp_clicks bigint, rfq_submits bigint)
language sql stable security definer set search_path = public as $$
  select d::date,
    count(distinct e.session_id) filter (where e.event is not null), count(*) filter (where e.event = 'page_view'), count(*) filter (where e.event = 'product_view'),
    count(*) filter (where e.event = 'search'), count(*) filter (where e.event = 'whatsapp_click'), count(*) filter (where e.event = 'rfq_submit')
  from generate_series(p_from, p_to, interval '1 day') d
  left join analytics_events e on (e.created_at at time zone 'Asia/Riyadh')::date = d::date
  where is_staff() group by d order by d
$$;

create or replace function admin_top_searches(p_from date, p_to date, p_limit int default 20)
returns table (query text, n bigint) language sql stable security definer set search_path = public as $$
  select lower(trim(e.query)), count(*) from analytics_events e
  where is_staff() and e.event = 'search' and e.query is not null and trim(e.query) <> '' and (e.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to
  group by 1 order by 2 desc limit least(p_limit, 100)
$$;

create or replace function admin_rfq_funnel(p_from date, p_to date)
returns table (status text, n bigint, quoted_value numeric) language sql stable security definer set search_path = public as $$
  select r.status::text, count(*), coalesce(sum(r.quoted_total),0) from rfqs r
  where is_staff() and (r.created_at at time zone 'Asia/Riyadh')::date between p_from and p_to group by 1 order by 2 desc
$$;

do $$ declare f text; begin
  foreach f in array array['admin_sales_report(date,date,text)','admin_sales_by_product(date,date,int)','admin_sales_by_category(date,date)','admin_traffic(date,date)','admin_top_searches(date,date,int)','admin_rfq_funnel(date,date)'] loop
    execute format('revoke all on function %s from public, anon', f); execute format('grant execute on function %s to authenticated', f);
  end loop; end $$;

-- ═════════ 0008_grants.sql ═════════
-- Explicit API privileges, so the setup does not depend on Supabase's default grants (which have changed between releases).
-- These grants only make tables *reachable*; Row Level Security (migration 0004) still decides which rows each role may see or change.
grant usage on schema public to anon, authenticated;
grant select on all tables in schema public to anon;
grant select, insert, update, delete on all tables in schema public to authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;

-- Functions the public storefront calls directly (everything else stays staff/authenticated-only, see 0004).
grant execute on function search_products(text,uuid,jsonb,text,text,text,int,int), product_facets(text,uuid), search_suggestions(text,int), public_best_sellers(int),
  submit_rfq(jsonb,jsonb), get_rfq_by_token(uuid), respond_rfq(uuid,boolean), track_event(text,text,text,uuid,uuid,text,text) to anon, authenticated;
grant execute on function is_staff(), is_admin(), setting_numeric(text,numeric), product_display_price(uuid), category_descendants(uuid), sku_in_use(text,uuid,uuid) to anon, authenticated;

